#include <stdlib.h>
#include <string.h>
#include <omp.h>
#if defined(__AVX512F__)
#include <immintrin.h>
#endif

#if defined(__AVX512F__)
#define VW 16
#define MR 12
#define ROWS(X) X(0) X(1) X(2) X(3) X(4) X(5) X(6) X(7) X(8) X(9) X(10) X(11)
typedef __m512 vt;
#define VZERO() _mm512_setzero_ps()
#define VLOAD(p) _mm512_load_ps(p)
#define VLOADU(p) _mm512_loadu_ps(p)
#define VSTOREU(p, v) _mm512_storeu_ps((p), (v))
#define VSET1(x) _mm512_set1_ps(x)
#define VFMA(a, b, c) _mm512_fmadd_ps((a), (b), (c))
#define VADD(a, b) _mm512_add_ps((a), (b))
#else
#define VW 8
#define MR 6
#define ROWS(X) X(0) X(1) X(2) X(3) X(4) X(5)
typedef float vt __attribute__((vector_size(VW * 4)));
static inline vt ldu_(const float *p) { vt v; memcpy(&v, p, sizeof(v)); return v; }
static inline void stu_(float *p, vt v) { memcpy(p, &v, sizeof(v)); }
#define VZERO() ((vt){0})
#define VLOAD(p) (*(const vt *)(p))
#define VLOADU(p) ldu_(p)
#define VSTOREU(p, v) stu_((p), (v))
#define VSET1(x) ((vt){0} + (x))
#define VFMA(a, b, c) ((a) * (b) + (c))
#define VADD(a, b) ((a) + (b))
#endif
#define NR (2 * VW)
#define KCMAX 256
#define NCW 256
#define NCP (NCW / NR)

static float *g_Ap = NULL, *g_Bp = NULL;
static size_t g_acap = 0, g_bcap = 0;

static float *grow(float *p, size_t *cap, size_t need)
{
    if (need <= *cap) return p;
    free(p);
    need = (need + 4095) & ~(size_t)4095;
    p = (float *)aligned_alloc(4096, need);
    *cap = need;
    return p;
}

/* a: packed [k][MR], b: packed [k][NR]; both zero padded, so always compute full tile */
static inline __attribute__((always_inline))
void kernel(int kc, const float *restrict a, const float *restrict b,
            float *restrict c, int ldc, int mr, int nr, int accum)
{
#define DECL(i) vt c##i##_0 = VZERO(), c##i##_1 = VZERO();
    ROWS(DECL)
#undef DECL

#define FMA(i) { vt av = VSET1(ak[i]); c##i##_0 = VFMA(av, b0, c##i##_0); \
                 c##i##_1 = VFMA(av, b1, c##i##_1); }
#define STEP(o) { const float *ak = a + (o) * MR; vt b0 = VLOAD(b + (o) * NR); \
                  vt b1 = VLOAD(b + (o) * NR + VW); ROWS(FMA) }
    int k = 0;
    for (; k + 4 <= kc; k += 4) {
        STEP(0) STEP(1) STEP(2) STEP(3)
        a += 4 * MR;
        b += 4 * NR;
    }
    for (; k < kc; k++) {
        STEP(0)
        a += MR;
        b += NR;
    }
#undef STEP
#undef FMA

    if (mr == MR && nr == NR) {
        if (accum) {
#define STA(i) { float *r = c + (size_t)(i) * ldc; \
                 VSTOREU(r, VADD(VLOADU(r), c##i##_0)); \
                 VSTOREU(r + VW, VADD(VLOADU(r + VW), c##i##_1)); }
            ROWS(STA)
#undef STA
        } else {
#define STS(i) { float *r = c + (size_t)(i) * ldc; VSTOREU(r, c##i##_0); VSTOREU(r + VW, c##i##_1); }
            ROWS(STS)
#undef STS
        }
    } else {
#if defined(__AVX512F__)
        __mmask16 m0 = nr >= 16 ? (__mmask16)0xFFFF : (__mmask16)((1u << nr) - 1);
        __mmask16 m1 = nr >= 32 ? (__mmask16)0xFFFF
                     : nr <= 16 ? (__mmask16)0 : (__mmask16)((1u << (nr - 16)) - 1);
#define STM(i) if ((i) < mr) { float *r = c + (size_t)(i) * ldc; \
            __m512 t0 = c##i##_0, t1 = c##i##_1; \
            if (accum) { t0 = _mm512_add_ps(t0, _mm512_maskz_loadu_ps(m0, r)); \
                         t1 = _mm512_add_ps(t1, _mm512_maskz_loadu_ps(m1, r + 16)); } \
            _mm512_mask_storeu_ps(r, m0, t0); _mm512_mask_storeu_ps(r + 16, m1, t1); }
        ROWS(STM)
#undef STM
#else
        float tmp[MR * NR] __attribute__((aligned(64)));
#define STT(i) { *(vt *)(tmp + (i) * NR) = c##i##_0; *(vt *)(tmp + (i) * NR + VW) = c##i##_1; }
        ROWS(STT)
#undef STT
        if (accum) {
            for (int i = 0; i < mr; i++)
                for (int j = 0; j < nr; j++)
                    c[(size_t)i * ldc + j] += tmp[i * NR + j];
        } else {
            for (int i = 0; i < mr; i++)
                for (int j = 0; j < nr; j++)
                    c[(size_t)i * ldc + j] = tmp[i * NR + j];
        }
#endif
    }
}

/* panel r: rows r*MR..r*MR+MR-1 of A, layout [k][MR] over all k */
static void pack_a_panel(const float *A, float *restrict dst, int r, int n)
{
    int row0 = r * MR;
    int mr = n - row0 < MR ? n - row0 : MR;
    const float *src = A + (size_t)row0 * n;
    int k0 = 0;
    if (mr == MR) {
        for (; k0 + 16 <= n; k0 += 16) {
            float t[MR][16] __attribute__((aligned(64)));
            for (int i = 0; i < MR; i++)
                memcpy(t[i], src + (size_t)i * n + k0, 16 * sizeof(float));
            float *d = dst + (size_t)k0 * MR;
            for (int kk = 0; kk < 16; kk++)
#pragma GCC unroll 16
                for (int i = 0; i < MR; i++)
                    d[kk * MR + i] = t[i][kk];
        }
    }
    for (; k0 < n; k0++) {
        float *d = dst + (size_t)k0 * MR;
        int i = 0;
        for (; i < mr; i++) d[i] = src[(size_t)i * n + k0];
        for (; i < MR; i++) d[i] = 0.0f;
    }
}

/* panel p: cols p*NR..p*NR+NR-1 of B, layout [k][NR] over all k */
static void pack_b_panel(const float *B, float *restrict dst, int p, int n)
{
    int j0 = p * NR;
    int nr = n - j0 < NR ? n - j0 : NR;
    const float *src = B + j0;
    if (nr == NR) {
        for (int k = 0; k < n; k++)
            memcpy(dst + (size_t)k * NR, src + (size_t)k * n, NR * sizeof(float));
    } else {
        for (int k = 0; k < n; k++) {
            int j = 0;
            for (; j < nr; j++) dst[(size_t)k * NR + j] = src[(size_t)k * n + j];
            for (; j < NR; j++) dst[(size_t)k * NR + j] = 0.0f;
        }
    }
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;
    int mp = (n + MR - 1) / MR;
    int np = (n + NR - 1) / NR;

    g_Ap = grow(g_Ap, &g_acap, (size_t)mp * MR * n * sizeof(float));
    g_Bp = grow(g_Bp, &g_bcap, (size_t)np * NR * n * sizeof(float));
    float *Ap = g_Ap, *Bp = g_Bp;

    int nkb = (n + KCMAX - 1) / KCMAX;
    int kcb = (n + nkb - 1) / nkb;

    int nth = omp_get_max_threads();
    int ntn = (np + NCP - 1) / NCP;

    /* pick tile height: balance rounds of tasks vs per-task B reuse */
    int mpt = 8;
    double best = 1e30;
    int lo = mp < 3 ? mp : 3;
    for (int m = 8; m >= lo && m >= 1; m--) {
        int ntm_ = (mp + m - 1) / m;
        int tasks = ntm_ * ntn;
        int rounds = (tasks + nth - 1) / nth;
        double cost = (double)rounds * m * (1.0 + 0.6 / m);
        if (cost < best - 1e-9) { best = cost; mpt = m; }
    }
    int ntm = (mp + mpt - 1) / mpt;

    #pragma omp parallel proc_bind(close)
    {
        #pragma omp for schedule(dynamic, 1)
        for (int t = 0; t < mp + np; t++) {
            if (t < mp) pack_a_panel(A, Ap + (size_t)t * n * MR, t, n);
            else        pack_b_panel(B, Bp + (size_t)(t - mp) * n * NR, t - mp, n);
        }

        #pragma omp for schedule(dynamic, 1) collapse(2)
        for (int ti = 0; ti < ntm; ti++) {
            for (int tj = 0; tj < ntn; tj++) {
                int p0 = ti * mpt, p1 = p0 + mpt < mp ? p0 + mpt : mp;
                int q0 = tj * NCP, q1 = q0 + NCP < np ? q0 + NCP : np;
                for (int pc = 0; pc < n; pc += kcb) {
                    int kc = n - pc < kcb ? n - pc : kcb;
                    int accum = pc > 0;
                    for (int p = p0; p < p1; p++) {
                        int i0 = p * MR;
                        int mr = n - i0 < MR ? n - i0 : MR;
                        const float *ap = Ap + (size_t)p * n * MR + (size_t)pc * MR;
                        float *crow = C + (size_t)i0 * n;
                        for (int q = q0; q < q1; q++) {
                            int j0 = q * NR;
                            int nr = n - j0 < NR ? n - j0 : NR;
                            const float *bp = Bp + (size_t)q * n * NR + (size_t)pc * NR;
                            kernel(kc, ap, bp, crow + j0, n, mr, nr, accum);
                        }
                    }
                }
            }
        }
    }
}
